#define _GNU_SOURCE
#include <ctype.h>
#include <dlfcn.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

static int is_numbered_proc_exe(const char *path) {
    const char *cursor;
    if (path == NULL || strncmp(path, "/proc/", 6) != 0) {
        return 0;
    }
    cursor = path + 6;
    if (!isdigit((unsigned char)*cursor)) {
        return 0;
    }
    while (isdigit((unsigned char)*cursor)) {
        cursor++;
    }
    return strcmp(cursor, "/exe") == 0;
}

ssize_t readlink(const char *path, char *buf, size_t size) {
    static ssize_t (*next_readlink)(const char *, char *, size_t);
    if (next_readlink == NULL) {
        next_readlink = dlsym(RTLD_NEXT, "readlink");
    }
    if (is_numbered_proc_exe(path)) {
        path = "/proc/self/exe";
    }
    return next_readlink(path, buf, size);
}

ssize_t readlinkat(int dirfd, const char *path, char *buf, size_t size) {
    static ssize_t (*next_readlinkat)(int, const char *, char *, size_t);
    if (next_readlinkat == NULL) {
        next_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
    }
    if (is_numbered_proc_exe(path)) {
        dirfd = AT_FDCWD;
        path = "/proc/self/exe";
    }
    return next_readlinkat(dirfd, path, buf, size);
}

